// Allocates one 0x28-byte D2SUnitMsgStrc from pUnit->pMemory with packet id 0xA3 (unit message) and enqueues it on pUnit's message list (pMsgFirst/pMsgLast, +0xEC/+0xF0). First block carries wArg1/wArg2/byParam and the source unit's type+GUID; second block carries dwParam1/dwParam2 and the target unit (pTarget) type+GUID, or GUID -1 when pTarget is NULL. Marks pUnit dirty via ROOM_LinkUnitToUpdateList.
// @sourcefile .\UNIT\SUnitMsg.cpp
void __fastcall SERVER_SendUnitMessagePacket(D2UnitStrc * pUnit, D2UnitStrc * pTarget, uint16_t wArg1, uint16_t wArg2, uint32_t dwParam1, uint32_t dwParam2, uint8_t byParam) {
    int32_t nUnitGUID;
    D2PoolManagerStrc* pMemPool = 0;
    if (pUnit) {
      pMemPool = pUnit->pMemory;
    }

    D2SUnitMsgStrc* pMsg = D2_NEW_POOL(pMemPool, D2SUnitMsgStrc);
    pMsg->nOpcode = '\0';
    pMsg->pad_0x5[0] = '\0';
    pMsg->pad_0x5[1] = '\0';
    pMsg->pad_0x5[2] = '\0';
    *(uint8_t*)&pMsg->uArgs = '\0';
    *(uint8_t*)((uintptr_t)&pMsg->uArgs + 1) = 0;
    *(uint16_t*)((uintptr_t)&pMsg->uArgs + 2) = 0;
    *(uint32_t*)&pMsg->uArgs.sA3.field_0x4 = 0;
    pMsg->uArgs.sA3.eUnitType = UNIT_PLAYER;
    pMsg->uArgs.sA3.nUnitGUID = 0;
    pMsg->uArgs.sA3.eTargetType = UNIT_PLAYER;
    pMsg->uArgs.sA3.nTargetGUID = 0;
    pMsg->uArgs.sA3.dwParam1 = 0;
    pMsg->uArgs.sA3.dwParam2 = 0;
    pMsg->pNext = 0;
    pMsg->uArgs.sA3.field_0x0 = byParam;
    pMsg->uArgs.sA3.field_0x4 = wArg2;
    pMsg->nOpcode = 0xa3;
    pMsg->uArgs.sA3.field_0x2 = wArg1;
    eD2UnitType eUnitType = UNIT_COUNT;
    if (pUnit) {
      eUnitType = pUnit->eUnitType;
    }

    pMsg->uArgs.sA3.eUnitType = eUnitType;
    if (!pUnit) {
      nUnitGUID = -1;
    } else {
      nUnitGUID = pUnit->nUnitGUID;
    }

    pMsg->uArgs.sA3.nUnitGUID = nUnitGUID;
    pMsg->uArgs.sA3.dwParam1 = dwParam1;
    pMsg->uArgs.sA3.dwParam2 = dwParam2;
    if (!pTarget) {
      pMsg->uArgs.sA3.nTargetGUID = -1;
    } else {
      pMsg->uArgs.sA3.eTargetType = pTarget->eUnitType;
      pMsg->uArgs.sA3.nTargetGUID = pTarget->nUnitGUID;
    }
    if (!pUnit->pMsgFirst) {
      pUnit->pMsgFirst = pMsg;
    }
    if (pUnit->pMsgLast) {
      pUnit->pMsgLast->pNext = pMsg;
    }

    pUnit->pMsgLast = pMsg;
    D2Common::Unit::ROOM_LinkUnitToUpdateList(pUnit);
}

// Clears STATE_skill_move on pUnit, allocates a D2SUnitMsgStrc (packet 0xA5) from the unit's memory pool, fills in the unit type, GUID, and wParam, appends it to the unit's message queue (pMsgFirst/pMsgLast), then calls ROOM_LinkUnitToUpdateList to schedule the unit for a network update.
// @sourcefile .\UNIT\SUnitMsg.cpp
void __fastcall UnitQueuePacket0xA5(D2UnitStrc * pUnit, uint16_t wParam) {
    D2PoolManagerStrc* pMemory;
    int nUnitGUID;
    D2Common::DATATBLS::ItemStats::SetState(pUnit, STATE_skill_move, 0);
    if (!pUnit) {
      pMemory = 0;
    } else {
      pMemory = pUnit->pMemory;
    }

    D2SUnitMsgStrc* pMsg = (D2SUnitMsgStrc*)D2_ALLOC_POOL(pMemory, 0x14);
    pMsg->nOpcode = '\0';
    pMsg->pad_0x5[0] = '\0';
    pMsg->pad_0x5[1] = '\0';
    pMsg->pad_0x5[2] = '\0';
    *(uint32_t*)&pMsg->uArgs.sA5.nUnitType = 0;
    pMsg->uArgs.sA5.nUnitGUID = 0;
    *(uint32_t*)&pMsg->uArgs.sA5.field_0x8 = 0;
    pMsg->pNext = 0;
    pMsg->nOpcode = 0xa5;
    uint8_t byUnitType = '\x06';
    if (pUnit) {
      byUnitType = (uint8_t)pUnit->eUnitType;
    }

    pMsg->uArgs.sA5.nUnitType = byUnitType;
    if (!pUnit) {
      nUnitGUID = -1;
    } else {
      nUnitGUID = pUnit->nUnitGUID;
    }

    pMsg->uArgs.sA5.nUnitGUID = nUnitGUID;
    pMsg->uArgs.sA5.field_0x8 = wParam;
    if (!pUnit->pMsgFirst) {
      pUnit->pMsgFirst = pMsg;
    }
    if (pUnit->pMsgLast) {
      pUnit->pMsgLast->pNext = pMsg;
    }

    pUnit->pMsgLast = pMsg;
    D2Common::Unit::ROOM_LinkUnitToUpdateList(pUnit);
}

